mapper.select:
select A.SEQ_ID seqId, CASE WHEN B.MATCH_STATUS IS NULL THEN #{TRD_MATCH_STATUS_01} ELSE B.MATCH_STATUS END matchStatus, F.MARCH_QTY / A.SHARE_AMT matchProgress, A.TRADE_MARKET tradeMarket, A.APPLY_TRADE_ID applyTradeId, A.SEC_ACCT_ID secAcctId, C.SEC_ACCT_NAME secAcctName, A.SEC_TYPE secType, CASE WHEN A.SEC_TYPE = #{SEC_TYPE_09} THEN NULL ELSE E.FINPROD_MARKET_ID END finprodMarketId, CASE WHEN A.SEC_TYPE = #{SEC_TYPE_09} THEN NULL ELSE E.FINPROD_ID END finprodId, CASE WHEN A.SEC_TYPE = #{SEC_TYPE_09} THEN NULL ELSE E.FINPROD_ABBR END finprodAbbr, E.FINPROD_TYPE2 finprodType2, A.SEAT_NUMBER seatNumber, A.TRADE_PLAT tradePlat, A.PS ps, A.SHARE_AMT - F.MARCH_QTY remainNum, A.FPRICE_AMT - F.MARCH_AMT remainAmount, A.UNIT_FPRICE unitFprice, A.UNIT_CPRICE unitCprice, A.CCY ccy, A.TRADE_DATE dealDate, A.TRADE_DATE tradeDate, D.ACCT_NO acctNo, D.ACCT_NAME acctName from SETTLE_TRANS_DATA_TOTAL A LEFT JOIN SETTLE_TRANS_DATA_TOTAL_STATUS B ON A.SEQ_ID = B.SEQ_NO AND (B.MATCH_STATUS IN (#{TRD_MATCH_STATUS_01},#{TRD_MATCH_STATUS_02}) OR B.MATCH_STATUS IS NULL) LEFT JOIN STL_SEC_ACCT_INFO C ON A.SEC_ACCT_ID = C.SEC_ACCT_ID LEFT JOIN STL_CAPACCT_INFO D ON D.ACCT_NO = A.ACCT_NO LEFT JOIN FIN_PRODUCT E ON E.FINPROD_ID = A.FINPROD_ID LEFT JOIN (select T.SEQ_NO, SUM(T.MARCH_QTY) MARCH_QTY,SUM(T.MARCH_AMT) MARCH_AMT from SETTLE_TRANS_DATA_TOTAL_MATCH T GROUP BY T.SEQ_NO) F ON A.SEQ_ID = F.SEQ_NO
AND A.TRADE_MARKET = #{tradeMarket}
AND A.TRADE_PLAT = #{tradePlat}
AND A.PS = #{ps}
AND A.SEC_ACCT_ID = #{secAcctNo}
AND (aa.APPLY_TRADE_ID IN
null) or aa.APPLY_TRADE_ID in (
#{item} )
AND E.FINPROD_MARKET_ID = #{tradeMarket}
AND A.TRADE_DATE >= to_date(#{tradeDateBegin},'yyyy-mm-dd')
AND A.TRADE_DATE <= to_date(#{tradeDateEnd},'yyyy-mm-dd')
AND (B.MATCH_STATUS = #{TRD_MATCH_STATUS_01} OR B.MATCH_STATUS IS NULL)
AND B.MATCH_STATUS = #{TRD_TRD_MATCH_STATUS_02}
AND A.FPRICE_AMT >= #{tradeAmt1}
AND A.FPRICE_AMT <= #{tradeAmt2}
